import {renderDaily,bindDaily} from './daily-view.mjs';
import {LABELS,predictTopic,validateComparison,validateArticles} from './topic-model.mjs';
const $ = (s) => document.querySelector(s);
const escape = (x) => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (x) => { try { const u=new URL(x); return u.protocol==='https:' ? escape(u.href) : '#'; } catch { return '#'; } };
const KEY='knowledge-pill-v1';
let saved={}; try { saved=JSON.parse(localStorage.getItem(KEY)||'{}'); } catch {}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({topic:state.topic,language:state.language,bookmarks:state.bookmarks,reviews:state.reviews}));}catch{toast('Device storage is unavailable. Changes will last for this session.');}}
function toast(message){document.querySelector('.flash')?.remove();const t=document.createElement('div');t.className='flash';t.role='status';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),4200);}
const date = () => new Intl.DateTimeFormat('en',{month:'long',day:'numeric'}).format(new Date());
function current(){return lessons.find(l=>l.topic===state.topic)||lessons[0];}
function setView(view){state.view=view;render();}
function setTopic(topic){if(!lessons.some(x=>x.topic===topic))throw Error('Unknown topic');state.topic=topic;state.view=state.view==='daily'?'daily':'today';persist();render();return {topic,lesson_id:current().id};}
function setLanguage(language){if(!['en','te'].includes(language))throw Error('Choose en or te');state.language=language;persist();render();return {language};}
function sourceList(lesson){return `<details class="sources"><summary>Sources & learning notes · ${lesson.sources.length} source${lesson.sources.length===1?'':'s'}</summary>${lesson.sources.map(s=>`<div class="source-item"><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}</a><time>${escape(s.date||'Publication date unknown')}</time></div>`).join('')}<p>${escape(lesson.evidence_note)}</p><p>Prepared ${escape(lesson.created_at)}. This is a foundational lesson, not today's news.</p></details>`;}
function lessonHTML(lesson){const c=lesson[state.language], done=state.reviews[lesson.id], bookmarked=state.bookmarks.includes(lesson.id);return `<article class="lesson" lang="${state.language}"><div class="lesson-top"><div class="badges"><span class="badge dark">${escape(lesson.topic)}</span><span class="badge">${lesson.minutes} min</span><span class="badge mint">${escape(lesson.kind)}</span></div><h2>${escape(c.title)}</h2><p>${escape(c.summary)}</p></div><div class="lesson-body"><section><div class="number-label">01 / ${state.language==='te'?'అర్థం చేసుకోండి':'UNDERSTAND'}</div><p>${escape(c.explain)}</p><div class="analogy"><p>${escape(c.analogy)}</p></div></section><section class="exercise"><div class="number-label">02 / ${state.language==='te'?'ప్రయత్నించండి':'TRY IT'}</div><h3>${state.language==='te'?'ఒక చిన్న పని':'Make the idea useful'}</h3><p>${escape(c.exercise)}</p></section><section class="recall"><div class="number-label">03 / ${state.language==='te'?'గుర్తు చేసుకోండి':'RECALL'}</div><h3>${escape(c.recall)}</h3><label for="recall-answer" class="notice">${state.language==='te'?'మీ మాటల్లో చెప్పండి. ఈ సమాధానం ఎక్కడికీ పంపబడదు.':'Explain it in your own words. Your answer is not sent anywhere.'}</label><textarea id="recall-answer" placeholder="${state.language==='te'?'నాకు అర్థమైనది…':'What I understood…'}"></textarea><button id="reveal">${state.language==='te'?'సమాధానం చూడండి':'Reveal the key idea'}</button><div id="answer-panel" class="hidden"><div class="answer"><p>${escape(c.answer)}</p></div><p class="notice">${state.language==='te'?'మీ అవగాహన ఎలా ఉంది?':'How well did you recall it?'}</p><div class="actions"><button class="primary" id="remembered">${state.language==='te'?'గుర్తుంది':'I remembered it'}</button><button id="review-again">${state.language==='te'?'మళ్ళీ చూడాలి':'Review tomorrow'}</button></div></div>${done?`<p class="notice">Next review: ${escape(new Date(done.due).toLocaleDateString())}. Self-assessed; not a test score.</p>`:''}</section><div class="actions"><button class="small" id="bookmark">${bookmarked?'Saved to your collection':'Save this pill'}</button><button class="small" id="next-topic">Next topic</button></div></div>${sourceList(lesson)}</article><p class="footer-note">Authored foundation lesson; not an automatically generated article summary. ${state.language==='te'?'Telugu translation is a draft awaiting fluent-speaker review.':''}</p>`;}
function collection(){const entries=lessons.filter(l=>state.bookmarks.includes(l.id)||state.reviews[l.id]);return `<div class="heading"><div><p class="eyebrow">KEEP WHAT MATTERS</p><h1>Your collection</h1><p>Saved pills and recall practice on this device.</p></div></div>${entries.length?entries.map(l=>`<article class="saved-card"><span class="badge">${escape(l.topic)}</span><h2>${escape(l[state.language].title)}</h2><p>${escape(l[state.language].summary)}</p><button class="small" data-open="${escape(l.topic)}">Read & review</button></article>`).join(''):`<div class="empty"><h2>Your first useful idea belongs here.</h2><p>Save a pill or complete its recall exercise to start your collection.</p><button id="back-today">Read a pill</button></div>`}`;}
async function readFile(file,validate,accept){if(!file)return;try{if(file.size>500000)throw Error('Choose a JSON file smaller than 500 KB.');accept(validate(JSON.parse(await file.text())));}catch(e){toast(e.message||'Could not read that file.');}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const definitions=[{name:'read_current_pill',description:'Read the selected learning pill and its sources.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({id:current().id,language:state.language,content:current()[state.language],sources:current().sources})},{name:'set_learning_language',description:'Change the visible lesson language and the device preference.',inputSchema:{type:'object',properties:{language:{type:'string',enum:['en','te']}},required:['language'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>setLanguage(input?.language)},{name:'open_topic_pill',description:'Open an available topic and save it as the device preference.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:['RAG','Fine-tuning','Agents']}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>setTopic(input?.topic)}];for(const d of definitions){try{Promise.resolve(context.registerTool(d,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}

let lessons=[], baseline=null, sourceCases=[];
let state={view:'daily',topic:['RAG','Fine-tuning','Agents'].includes(saved.topic)?saved.topic:'RAG',language:saved.language==='te'?'te':'en',bookmarks:Array.isArray(saved.bookmarks)?saved.bookmarks:[],reviews:saved.reviews&&typeof saved.reviews==='object'?saved.reviews:{},articles:null,metric:null,route:null,input:''};
function readingList(){
  if(!state.articles)return '';
  const packet=state.articles,entries=packet.articles.filter(a=>a.label===state.topic);
  return `<section class="panel"><p class="eyebrow">READING MATCHED TO ${escape(state.topic)}</p><h2>${entries.length} article${entries.length===1?'':'s'} for your interest</h2><p class="notice">${packet.source_mode==='historical_paper_examples'?'Historical paper examples':'Recent editorial feed at the time of collection'} · Imported labels: ${escape(packet.engine)}. Open the source for the full article; the lesson below teaches the general topic.</p>${entries.map(a=>`<div class="source-item"><a href="${safeUrl(a.source_url)}" target="_blank" rel="noopener noreferrer">${escape(a.title)}</a>${a.published_at?`<time>${escape(new Date(a.published_at).toLocaleDateString())}</time>`:''}</div>`).join('')}${entries.length?'':'<p>No imported articles have this label. Choose another interest or import a new batch.</p>'}</section>`;
}
function today(){
  const l=current();const due=Object.values(state.reviews).filter(r=>r&&new Date(r.due)<=new Date()).length;
  return `<div class="heading"><div><p class="eyebrow">YOUR AI LEARNING SPACE</p><h1>One idea. A little further.</h1><p>${due?`${due} pill${due===1?' is':'s are'} ready for review.`:'Choose an interest. Read, try it, then explain it back.'}</p></div><span class="date">${date()}</span></div>${readingList()}${lessonHTML(l)}`;
}
function studio(){
  const r=state.route;
  return `<div class="heading"><div><p class="eyebrow">FIND RELEVANT READING</p><h1>Which AI topic is this?</h1><p>Turn an article description into a useful learning direction.</p></div></div>
  <section class="panel"><label for="article-text">English title and short description</label><textarea id="article-text" rows="5" maxlength="4000" placeholder="An assistant retrieves relevant pages from a company handbook and uses them to answer employees’ questions with citations.">${escape(state.input)}</textarea><div class="actions"><button class="primary" id="route-article">Find the topic</button><button id="use-example">Try a paper example</button></div><p class="notice">Starter router: TF-IDF + logistic regression. It runs on this device. Fine-tuned Qwen runs in the project notebook.</p>
  ${r?`<div class="answer" role="status"><span class="badge dark">${escape(r.label)}</span><p>${r.label==='Other'?'This description falls outside our three learning topics or has no recognized topic features. No lesson is selected.':'Suggested topic: '+escape(r.label)+'. Open a short foundation lesson to understand the idea.'}</p>${r.label==='Other'?'':`<button class="primary" data-open="${escape(r.label)}">Open the matching pill</button>`}<p class="notice">${escape(r.engine)}. This is a topic suggestion; it does not check whether the article is true.</p></div>`:''}</section>
  <section class="panel"><h2>Bring in your trained model’s choices</h2><p>Run the notebook, then import <code>routed_articles.json</code>. Your reading list will show its topic assignments and source links.</p><label class="file-label">Import routed articles<input type="file" id="articles-input" accept="application/json,.json"></label>${state.articles?`<p>${state.articles.articles.length} articles loaded. <button class="small" id="view-reading">View my reading</button></p>`:''}<p class="notice">Imports stay in this browser session. Daily pills have a separate scheduled workflow. These are the trained router’s imported article choices.</p></section>`;
}
function metricsTable(results){
  return `<div class="table-wrap"><table><thead><tr><th>Model</th><th>Accuracy</th><th>Macro F1</th><th>Examples</th></tr></thead><tbody>${['lexical','baseline','finetuned'].filter(k=>results[k]).map(k=>`<tr><td>${({lexical:'Simple text classifier',baseline:'Qwen base',finetuned:'Qwen + LoRA, merged'})[k]}</td><td>${(results[k].accuracy*100).toFixed(1)}%</td><td>${results[k].macro_f1.toFixed(3)}</td><td>${results[k].n}</td></tr>`).join('')}</tbody></table></div>`;
}
function experiment(){
  const m=state.metric;
  return `<div class="heading"><div><p class="eyebrow">THE WEEK 5 EXPERIMENT</p><h1>Does fine-tuning help?</h1><p>One classification task. The same examples before and after.</p></div></div>
  <section class="panel"><h2>Article → RAG, Agents, Fine-tuning or Other</h2><p>Qwen3-1.7B-Base, trained with LoRA on 400 rows and evaluated on 100 validation rows. Variations of each scenario stay together in one split.</p><div class="alert">${m?'Results imported from your notebook. This app checks the report format; it does not independently verify the run.':'Colab training and evaluation completed. The exported predictions, data hashes and metrics were verified. The browser uses the simple classifier; Qwen runs in the training notebook.'}</div><label class="file-label">Import measured results<input type="file" id="metrics-input" accept="application/json,.json"></label>${m?`<h3>Authored validation</h3>${metricsTable(m)}${m.source_cases?`<h3>16 source-based examples</h3>${metricsTable(m.source_cases)}`:''}`:`<div class="table-wrap"><table><thead><tr><th>Model</th><th>Validation accuracy</th><th>Paper accuracy</th><th>Paper macro F1</th></tr></thead><tbody><tr><td>Simple text classifier</td><td>100/100</td><td>15/16</td><td>0.937</td></tr><tr><td>Qwen base</td><td>25/100</td><td>4/16</td><td>0.100</td></tr><tr><td>Qwen + LoRA</td><td>100/100</td><td>14/16</td><td>0.867</td></tr></tbody></table></div><p>The trained model passed all five smoke tests. Its two paper errors were CLIP and Whisper, predicted Fine-tuning instead of Other. These small sets do not establish real-world reliability.</p>`}<p class="notice">500 rows represent 100 authored scenarios with five variations each. Validation contains 20 scenario groups. The 16 paper summaries and labels were authored for this project and have not been independently reviewed.</p></section>
  <section class="panel"><h2>Project files and evidence</h2><p>Upload the notebook to Google Colab, choose a GPU and run its numbered steps. Data and helper code are included.</p><div class="actions"><a href="https://github.com/DRKREDDY5/Knowledge-Pill" target="_blank" rel="noopener noreferrer">GitHub project and actual results</a><a href="downloads/Knowledge_Pill_Simple.ipynb" download>Download the Colab notebook</a><a href="downloads/Knowledge_Pill_Week5.zip" download>Source ZIP for submission</a></div><p class="notice">Prepare data → measure base → train LoRA → merge → five smoke tests → compare → route reading. The source ZIP is optional for running the notebook.</p></section>`;
}
function render(){
  document.body.lang=state.language;document.documentElement.lang='en';
  document.body.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><span class="mark" aria-hidden="true"></span>Knowledge Pill</div><nav class="nav" aria-label="Main navigation">${[['daily','Daily pills'],['today','Foundations'],['studio','Article router'],['collection','Collection'],['experiment','Experiment']].map(([id,label])=>`<button data-view="${id}" aria-pressed="${state.view===id}">${label}</button>`).join('')}</nav></header><div class="workspace"><aside><div class="profile"><div><label for="language">Learning language</label><select id="language"><option value="en" ${state.language==='en'?'selected':''}>English</option><option value="te" ${state.language==='te'?'selected':''}>తెలుగు · Telugu</option></select></div><div><label for="audience">Built for</label><select id="audience"><option>Developers learning AI</option></select></div></div><p class="eyebrow">YOUR INTERESTS</p><div class="topics">${['RAG','Fine-tuning','Agents'].map((t,i)=>`<button class="topic ${state.topic===t?'active':''}" data-topic="${t}" aria-pressed="${state.topic===t}"><span>${t}</span><span>0${i+1}</span></button>`).join('')}</div><p class="side-note">One concept, one application, one thing to remember.</p><p class="side-note">Your preferences and progress stay on this device.</p></aside><main id="main">${state.view==='daily'?renderDaily(state.topic,state.language):state.view==='today'?today():state.view==='collection'?collection():state.view==='studio'?studio():experiment()}</main></div></div>`;
  bind();
}
function bind(){
  if(state.view==='daily')bindDaily(state.topic,state.language,render,toast,()=>setView('today'));
  document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));
  document.querySelectorAll('[data-topic],[data-open]').forEach(x=>x.onclick=()=>setTopic(x.dataset.topic||x.dataset.open));
  $('#language').onchange=e=>setLanguage(e.target.value);
  if($('#back-today'))$('#back-today').onclick=()=>setView('today');
  if($('#reveal'))$('#reveal').onclick=()=>{$('#answer-panel').classList.remove('hidden');$('#reveal').classList.add('hidden');};
  for(const [id,days]of [['remembered',3],['review-again',1]])if($('#'+id))$('#'+id).onclick=()=>{state.reviews[current().id]={due:new Date(Date.now()+days*86400000).toISOString(),last_review:new Date().toISOString(),self_assessment:id};persist();toast(`Saved. Review in ${days} day${days===1?'':'s'}.`);render();};
  if($('#bookmark'))$('#bookmark').onclick=()=>{const id=current().id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();render();};
  if($('#next-topic'))$('#next-topic').onclick=()=>{const i=lessons.indexOf(current());setTopic(lessons[(i+1)%lessons.length].topic);};
  if($('#article-text'))$('#article-text').oninput=e=>{state.input=e.target.value;};
  if($('#route-article'))$('#route-article').onclick=()=>{try{state.route=predictTopic(state.input,baseline);render();}catch(e){toast(e.message);}};
  if($('#use-example'))$('#use-example').onclick=()=>{state.input=sourceCases[Math.floor(Math.random()*sourceCases.length)].text;state.route=null;render();};
  if($('#articles-input'))$('#articles-input').onchange=e=>readFile(e.target.files[0],validateArticles,a=>{state.articles=a;render();});
  if($('#metrics-input'))$('#metrics-input').onchange=e=>readFile(e.target.files[0],validateComparison,m=>{state.metric=m;render();});
  if($('#view-reading'))$('#view-reading').onclick=()=>setView('today');
}
try{
  const responses=await Promise.all(['lessons.json','router_baseline.json','source_cases.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error('Could not load the learning library. Please reload.');return r.json();}));
  [lessons,baseline,sourceCases]=responses;render();registerTools();
}catch(e){const target=$('#app');if(target)target.textContent=e.message;}
